using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Web.Script.Serialization;using System.Windows.Forms;
namespace Synkoz {
 public sealed class GraphPresetR6 {public int Version=13;public List<GraphNode15> Nodes=new List<GraphNode15>();public List<GraphWire15> Wires=new List<GraphWire15>();public List<Effect936> Effects=new List<Effect936>();public Dictionary<string,string> Assets=new Dictionary<string,string>();}
 public static class PresetsR6 {
  static IEnumerable<string> Assets(GraphPresetR6 p){return p.Nodes.SelectMany(n=>n.CompositionR21==null?new GraphNode15[]{n}:new[]{n}.Concat(n.CompositionR21.Steps.SelectMany(step=>step.Sources))).Select(n=>n.ImageFileR6).Concat(p.Effects.Select(e=>e.Asset)).Concat(p.Effects.Select(e=>e.WaitingR20.Asset)).Concat(p.Effects.SelectMany(e=>e.AnimationsR9)).Concat(p.Effects.SelectMany(e=>e.BanksR16.Items.Select(b=>b.Asset))).Concat(p.Effects.Where(e=>e.Kind==EffectKind936.Texte).Select(e=>e.TextR12.FontFileR2)).Where(s=>!string.IsNullOrEmpty(s)).Distinct();}
  public static GraphPresetR6 Pack(Montage m,TrackFx936 fx,IEnumerable<string> ids){var selected=new HashSet<string>(ids);var p=new GraphPresetR6{Nodes=UiR2.Copy(fx.Graph15.Nodes.Where(n=>selected.Contains(n.Id)).ToList()),Wires=UiR2.Copy(fx.Graph15.Wires.Where(w=>selected.Contains(w.From)&&selected.Contains(w.To)).ToList()),Effects=UiR2.Copy(fx.Effects.Where(e=>fx.Graph15.Nodes.Any(n=>selected.Contains(n.Id)&&n.EffectId==e.IdR8)).ToList())};if(p.Nodes.Count==0)throw new Exception("Sélectionner au moins un module (Ctrl + clic).");foreach(var asset in Assets(p)){string path=Path.IsPathRooted(asset)?asset:Store934.MediaPath(m.Folder,asset);p.Assets[asset]=Convert.ToBase64String(File.ReadAllBytes(path));}return p;}
  public static void Import(Montage m,TrackFx936 fx,GraphPresetR6 p){if(p==null||(p.Version!=1&&p.Version!=2&&p.Version!=3&&p.Version!=4&&p.Version!=5&&p.Version!=6&&p.Version!=7&&p.Version!=8&&p.Version!=9&&p.Version!=10&&p.Version!=11&&p.Version!=12&&p.Version!=13)||p.Nodes==null||p.Wires==null||p.Effects==null||p.Assets==null||p.Nodes.Count==0||p.Nodes.Count>256)throw new Exception("Preset modulaire invalide.");p=UiR2.Copy(p);var used=new HashSet<int>(fx.Graph15.Nodes.Where(n=>n.Finished||n.ListenVirtual>0).Select(n=>n.ListenVirtual>0?n.ListenVirtual:n.VirtualTrack));var virtuals=new Dictionary<int,int>();foreach(int v in p.Nodes.Where(n=>n.Finished).Select(n=>n.VirtualTrack).Distinct()){int free=Enumerable.Range(17,16).FirstOrDefault(x=>!used.Contains(x));if(free==0)throw new Exception("Aucune destination virtuelle libre.");used.Add(free);virtuals[v]=free;}foreach(var n in p.Nodes){int mapped;if(n.Finished&&virtuals.TryGetValue(n.VirtualTrack,out mapped))n.VirtualTrack=mapped;if(n.ListenVirtual>0&&virtuals.TryGetValue(n.ListenVirtual,out mapped))n.ListenVirtual=mapped;n.MidiR4.ChannelsR9=n.MidiR4.ChannelsR9.Select(c=>virtuals.ContainsKey(c)?virtuals[c]:c).Distinct().ToList();}var ids=p.Nodes.ToDictionary(n=>n.Id,n=>n.Kind==GraphKind15.Output?fx.Graph15.Nodes.Single(x=>x.Kind==GraphKind15.Output).Id:Guid.NewGuid().ToString("N"));var effects=p.Effects.ToDictionary(e=>e.IdR8,e=>Guid.NewGuid().ToString("N"));Action<MidiSelectR4> remap=s=>{if(s==null)return;if(ids.ContainsKey(s.Origin))s.Origin=ids[s.Origin];if(s.Channel>=16&&virtuals.ContainsKey(s.Channel+1))s.Channel=virtuals[s.Channel+1]-1;if(s.Track>=17&&virtuals.ContainsKey(s.Track))s.Track=virtuals[s.Track];if(s.FilterR12!=null)s.FilterR12.ChannelsR9=s.FilterR12.ChannelsR9.Select(c=>virtuals.ContainsKey(c)?virtuals[c]:c).ToList();};foreach(var n in p.Nodes){n.Id=ids[n.Id];n.X+=25;n.Y+=25;if(!string.IsNullOrEmpty(n.EffectId))n.EffectId=effects[n.EffectId];remap(n.ActivationR4);remap(n.CameraR19.Input);remap(n.ActivityR20.Listen);if(n.MixerR20!=null)foreach(var source in n.MixerR20.Sources)source.Node=ids.ContainsKey(source.Node)?ids[source.Node]:"";if(n.CompositionR21!=null)foreach(var source in n.CompositionR21.Steps.SelectMany(step=>step.Sources)){foreach(var binding in source.ControlsR12)remap(binding.Input);if(!m.Tracks.Any(t=>t.SourceKey15==source.MediaTrack))source.MediaTrack="";}foreach(var binding in n.ControlsR12)remap(binding.Input);if(!string.IsNullOrEmpty(n.MediaTrack)&&!m.Tracks.Any(t=>t.SourceKey15==n.MediaTrack))n.MediaTrack="";}foreach(var e in p.Effects){e.IdR8=effects[e.IdR8];foreach(var b in new[]{e.Amplitude15,e.Radius15,e.Phase15,e.SpeedTbo15,e.OpacityR4,e.MoveXR19,e.MoveYR19})remap(b.MidiR4);if(!string.IsNullOrEmpty(e.ParentR8))e.ParentR8=effects.ContainsKey(e.ParentR8)?effects[e.ParentR8]:null;}foreach(var w in p.Wires){w.From=ids[w.From];w.To=ids[w.To];}var candidate=UiR2.Copy(fx);candidate.Graph15.Nodes.AddRange(p.Nodes.Where(n=>n.Kind!=GraphKind15.Output));candidate.Graph15.Wires.AddRange(p.Wires);candidate.Effects.AddRange(p.Effects);GraphRules15.Validate(candidate);
   var mapping=new Dictionary<string,string>();foreach(var asset in Assets(p)){string data;if(!p.Assets.TryGetValue(asset,out data))throw new Exception("Ressource absente du preset : "+Path.GetFileName(asset));string ext=Path.GetExtension(asset).ToLowerInvariant();if(!new[]{".png",".gif",".jpg",".jpeg",".bmp",".mp4",".ttf",".otf"}.Contains(ext))throw new Exception("Type de ressource non pris en charge.");byte[] bytes=Convert.FromBase64String(data);string relative=Path.Combine(ProjectStorageR11.Resources(m),"Preset_"+Guid.NewGuid().ToString("N")+ext);File.WriteAllBytes(Store934.MediaPath(m.Folder,relative),bytes);mapping[asset]=ext==".ttf"||ext==".otf"?Store934.MediaPath(m.Folder,relative):relative;}foreach(var n in p.Nodes.SelectMany(node=>node.CompositionR21==null?new[]{node}:new[]{node}.Concat(node.CompositionR21.Steps.SelectMany(step=>step.Sources))))if(!string.IsNullOrEmpty(n.ImageFileR6))n.ImageFileR6=mapping[n.ImageFileR6];foreach(var e in p.Effects){if(!string.IsNullOrEmpty(e.Asset))e.Asset=mapping[e.Asset];if(!string.IsNullOrEmpty(e.WaitingR20.Asset))e.WaitingR20.Asset=mapping[e.WaitingR20.Asset];e.AnimationsR9=e.AnimationsR9.Select(a=>mapping[a]).ToList();foreach(var bank in e.BanksR16.Items)if(!string.IsNullOrEmpty(bank.Asset))bank.Asset=Store934.MediaPath(m.Folder,mapping[bank.Asset]);if(e.Kind==EffectKind936.Texte&&!string.IsNullOrEmpty(e.TextR12.FontFileR2))e.TextR12.FontFileR2=mapping[e.TextR12.FontFileR2];}fx.Graph15.Nodes.AddRange(p.Nodes.Where(n=>n.Kind!=GraphKind15.Output));fx.Graph15.Wires.AddRange(p.Wires);fx.Effects.AddRange(p.Effects);
  }
 }
 public sealed partial class EffectsForm936 {
